import React, { useEffect, useState } from 'react';
import { SafeAreaView, View, Text, TouchableOpacity, Image, ActivityIndicator } from 'react-native';
import tw from 'twrnc';
import axios from 'axios';
import Constants from 'expo-constants';
import { AirbnbRating } from 'react-native-ratings';
import { useLocalSearchParams } from 'expo-router';
import Chapters from '@/components/Chapters';
import Related from '@/components/Related';
import Reviews from '@/components/Reviews';
import AudioPlayer from '@/components/AudioPlayer';
import { useThemeColor } from '@/hooks/useThemeColor'
import { ThemedView } from '@/components/ThemedView';
import { ThemedText } from '@/components/ThemedText';

const BookDetails = ({ defaultRating = 4 }) => {
  const { bookId } = useLocalSearchParams();
  const [book, setBook] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedTab, setSelectedTab] = useState('Chapters');
  const [selectedChapter, setSelectedChapter] = useState(null);
  const [currentSound, setCurrentSound] = useState(null);

  const apiUrl = Constants.expoConfig?.extra?.API_BASE_URL;

  useEffect(() => {
    if (!bookId) return;

    setLoading(true);
    axios
      .get(`${apiUrl}/book/${bookId}`)
      .then((res) => {
        setBook(res.data.book);
        setLoading(false);
      })
      .catch((err) => {
        setError(err.message);
        setLoading(false);
      });
  }, [bookId]);

  const renderTabContent = () => {
    switch (selectedTab) {
      case 'Chapters':
        return (
          <Chapters
            book={book}
            selectedChapter={selectedChapter}
            setSelectedChapter={setSelectedChapter}
            currentSound={currentSound}
            setCurrentSound={setCurrentSound}
          />
        );
      case 'Related':
        return <Related />;
      case 'Reviews':
        return <Reviews />;
      default:
        return null;
    }
  };

  if (loading) {
    return (
      <ThemedView style={tw`flex-1 justify-center items-center`}>
        <ActivityIndicator size="large" color="#ff1493" />
         <ThemedText style={{ color: textColor, marginTop: 10 }}>Loading audiobook</ThemedText>
      </ThemedView>
    );
  }

  if (error) {
    return (
      <ThemedView style={tw`flex-1 justify-center items-center p-4`}>
        <ThemedText style={tw`text-red-500 text-lg`}>Error: {error}</ThemedText>
      </ThemedView>
    );
  }

  if (!book) {
    return (
      <ThemedView style={tw`flex-1 justify-center items-center p-4`}>
        <ThemedText style={tw`text-gray-500 text-lg`}>Book not found</ThemedText>
      </ThemedView>
    );
  }

  return (
    <SafeAreaView style={tw`flex-1`}>
      <ThemedView style={tw`p-4`}>
        {/* Header */}
        <ThemedView style={tw`flex-row mb-4 items-center`}>
          <TouchableOpacity onPress={() => console.log('Back pressed')}>
            <ThemedText style={tw`text-lg mr-4`}>←</ThemedText>
          </TouchableOpacity>
          <ThemedText style={tw`text-3xl font-bold`}>{book.title}</ThemedText>
        </ThemedView>

        {/* Book Details */}
        <ThemedView style={tw`flex-row mb-4 items-center`}>
          <Image
            source={{ uri: book.coverImage }}
            style={tw`w-32 h-32 mr-3 rounded-lg`}
            resizeMode="cover"
          />
          <ThemedView>
            <ThemedText style={tw`text-base text-[#ff1493] font-semibold`}>
              {book.author}
            </ThemedText>
            <ThemedText style={tw`text-base text-[#ff1493]`}>
              Read by: {book.reciter}
            </ThemedText>
          </ThemedView>
        </ThemedView>

        {/* Ratings */}
        <ThemedView style={tw`mb-3 flex-row items-center`}>
          <AirbnbRating
            count={5}
            defaultRating={defaultRating}
            size={18}
            showRating={false}
            selectedColor="#FFD700"
            unSelectedColor={'#323232B3'}
          />
        </ThemedView>

        {/* Book Description */}
        <ThemedText style={tw`text-sm mb-4`}>{book.description}</ThemedText>

        {/* Tabs */}
        <ThemedView style={tw`flex-row justify-between border-b pb-2`}>
          {['Chapters', 'Reviews', 'Related'].map((tab) => (
            <TouchableOpacity key={tab} onPress={() => setSelectedTab(tab)} style={tw`flex-1`}>
              <ThemedView style={tw`items-center`}>
                <ThemedText
                  style={[
                    tw`text-lg p-2`,
                    { color: selectedTab === tab ? '#070c70' : '#999' },
                  ]}
                >
                  {tab}
                </ThemedText>
                {selectedTab === tab && <ThemedView style={tw`h-1 w-full bg-[#ff1493]`} />}
              </ThemedView>
            </TouchableOpacity>
          ))}
        </ThemedView>

        {/* Tab Content */}
        {renderTabContent()}
      </ThemedView>

      {/* Audio Player */}
      {selectedChapter && (
        <AudioPlayer
          audio={selectedChapter.audio}
          bookName={book.title}
          chapterTitle={selectedChapter.title}
          onClose={() => setSelectedChapter(null)}
        />
      )}
    </SafeAreaView>
  );
};

export default BookDetails;
